package edu.pe.cibertec.saibm.membresia.infrastructure.config; import java.time.Instant; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import edu.pe.cibertec.saibm.membresia.application.port.in.MembershipUseCase; @Component public class MembershipExpiryJob {private final MembershipUseCase use;public MembershipExpiryJob(@Qualifier("membership") MembershipUseCase u){use=u;}@Scheduled(fixedDelayString="${membresia.expiry.delay-ms:60000}")public void expire(){use.expireDue(Instant.now(),"scheduled-expiry");}}
